// Ticket is lottery ticket payment in a probabilistic micropayment protocol
// The expected value of the ticket constitutes the payment and can be
// calculated using the ticket's face value and winning probability
type Ticket struct {
	// Recipient is the ETH address of recipient
	Recipient ethcommon.Address

	// Sender is the ETH address of sender
	Sender ethcommon.Address

	// FaceValue represents the pay out to
	// the recipient if the ticket wins
	FaceValue *big.Int

	// WinProb represents how likely a ticket will win
	WinProb *big.Int

	// SenderNonce is the monotonically increasing counter that makes
	// each ticket unique given a particular recipientRand value
	SenderNonce uint32

	// RecipientRandHash is the 32 byte keccak-256 hash commitment to a random number
	// provided by the recipient. In order for the recipient to redeem
	// a winning ticket, it must reveal the preimage to this hash
	RecipientRandHash ethcommon.Hash

	// CreationRound is the round during which the ticket is created
	CreationRound int64

	// CreationRoundBlockHash is the block hash associated with CreationRound
	CreationRoundBlockHash ethcommon.Hash

	// ParamsExpirationBlock is the block number at which the ticket parameters used
	// to create the ticket will no longer be valid
	ParamsExpirationBlock *big.Int

	PricePerPixel *big.Rat
}

// TicketStore is an interface which describes an object capable
// of persisting tickets
type TicketStore interface {
	// SelectEarliestWinningTicket selects the earliest stored winning ticket for a 'sender'
	// which is not yet redeemed
	SelectEarliestWinningTicket(sender ethcommon.Address, minCreationRound int64) (*SignedTicket, error)

	// RemoveWinningTicket removes a ticket
	RemoveWinningTicket(ticket *SignedTicket) error

	// StoreWinningTicket stores a signed ticket
	StoreWinningTicket(ticket *SignedTicket) error

	// MarkWinningTicketRedeemed stores the on-chain transaction hash and timestamp of redemption
	// This marks the ticket as being 'redeemed'
	MarkWinningTicketRedeemed(ticket *SignedTicket, txHash ethcommon.Hash) error

	// WinningTicketCount returns the amount of non-redeemed winning tickets for a sender in the TicketStore
	WinningTicketCount(sender ethcommon.Address, minCreationRound int64) (int, error)

	// IsOrchActive returns true if the given orchestrator addr is active in the given round
	IsOrchActive(addr ethcommon.Address, round *big.Int) (bool, error)

	// ManifestID should go away once we do direct push of video
	ManifestID core.ManifestID

	// Bytes of the source video segment
	Source *stream.HLSSegment

	// Rendition parameters to be checked
	Profiles []ffmpeg.VideoProfile

	// Information on the orchestrator that performed the transcoding
	Orchestrator *net.OrchestratorInfo

	// Transcoded result metadata
	Results *net.TranscodeData

	// Rendition locations; typically when the data is in object storage
	URIs []string

	// Cached data when local object storage is used
	Renditions [][]byte

	// External object storage used by broadcaster (can be defined per-stream)
	OS drivers.OSSession
}

type Results struct {
	// Verifier specific score
	Score float64

	// Number of pixels decoded in this result
	Pixels []int64
}

type Verifier interface {
	Verify(params *Params) (*Results, error)
}

type Policy struct {

	// Verification function to run
	Verifier Verifier

	// Maximum number of retries until the policy chooses a winner
	Retries int

	// How often to invoke the verifier, on a per-segment basis
	SampleRate float64 // XXX for later

	// How many parallel transcodes to support
	Redundancy int // XXX for later
}

type SegmentVerifierResults struct {
	params *Params
	res    *Results

}

if sv.policy == nil {
	return nil, nil
}

var err error
res := &Results{}

// TODO Use policy sampling rate to determine whether to invoke verifier.
//      If not, exit early. Seed sample using source data for repeatability!
if sv.policy.Verifier != nil {
	res, err = sv.policy.Verifier.Verify(params)
}

// Check pixel counts
if (err == nil || (err != ErrAudioMismatch && IsRetryable(err))) && res != nil && params.Results != nil {
	pxls := res.Pixels
	if len(pxls) != len(params.Results.Segments) {
		pxls, err = countPixelParams(params)
	}
	for i := 0; err == nil && i < len(params.Results.Segments) && i < len(pxls); i++ {
		reportedPixels := params.Results.Segments[i].Pixels
		verifiedPixels := pxls[i]
		if reportedPixels != verifiedPixels {
			err = ErrPixelMismatch
		}
	}
}

if err == nil {
	// Verification passed successfully, so use this set of params
	return params, nil
}
sv.count++

func IsFatal(err error) bool {
	_, fatal := err.(Fatal)
	return fatal
}

func IsRetryable(err error) bool {
	_, retryable := err.(Retryable)
	return retryable || IsFatal(err)
}

func (sv *SegmentVerifier) sigVerification(params *Params) error {
	if params.Orchestrator == nil || params.Orchestrator.Address == nil || params.Orchestrator.TicketParams == nil {
		return nil
	}

	if len(params.Results.Segments) != len(params.Renditions) {
		return errPMCheckFailed
	}

	segHashes := make([][]byte, len(params.Renditions))
	for i := range params.Renditions {
		segHashes[i] = crypto.Keccak256(params.Renditions[i])
	}

	// Verify the signature against the orchestrator provided address if it exists
	// Otherwise verify the signature against the ticket recipient address
	addr := ethcommon.BytesToAddress(params.Orchestrator.Address)
	if (addr == ethcommon.Address{}) {
		addr = ethcommon.BytesToAddress(params.Orchestrator.TicketParams.Recipient)
	}

	if !sv.verifySig(
		addr,
		crypto.Keccak256(segHashes...),
		params.Results.Sig) {
		glog.Error("Sig check failed")
		return errPMCheckFailed
	}
	return nil
}

func countPixelParams(params *Params) ([]int64, error) {

	if len(params.Results.Segments) != len(params.Renditions) {
		return nil, ErrPixelsAbsent
	}

	pxls := make([]int64, len(params.Results.Segments))

	for i := 0; i < len(params.Results.Segments); i++ {
		count, err := countPixels(params.Renditions[i])
		if err != nil {
			return nil, err
		}
		pxls[i] = count
	}
	return pxls, nil
}

